import { createFastDB, MemoryPendingWriteStore, objects, UncertainWriteError, RecordId } from '@cossackframework/fastdb';

const db = createFastDB({
    url: 'http://127.0.0.1:4321',
    token: 'local-service-token',
    // Use FilePendingWriteStore (Node) or DurableObjectPendingWriteStore (Workers) in production.
    pending: new MemoryPendingWriteStore(),
    workLimits: { read: { rowsRead: 10_000 }, write: { rowMutations: 100 } },
});

export async function rename(id: string, title: string, signal: AbortSignal): Promise<number> {
    try {
        const result = await db.write([
            { sql: 'UPDATE posts SET title = $title WHERE id = $id', params: { $title: title, $id: new RecordId('posts', id) } },
        ], { signal, kind: 'posts.rename' });
        return Number(result.results[0]!.affected);
    } catch (error) {
        // The write is saved; recoverPending() replays the exact request later.
        if (error instanceof UncertainWriteError) return -1;
        throw error;
    }
}

export async function titles(): Promise<string[]> {
    const result = await db.read([{ sql: 'SELECT title FROM posts ORDER BY title LIMIT 20' }]);
    return objects<{ title: string }>(result.results[0]!).map(row => row.title);
}

import { Float64, RecordId, Vector, fromTransport, toTransport, type Value } from '@cossackframework/fastdb/values';

const record: Value = {
    id: new RecordId('tickets', 7n),
    owner: new RecordId('users', 'ada'),
    score: new Float64(1),
    embedding: Vector.float32([0.25, 0.5]),
};

// JSON-safe for SSR state, RPC and plugin boundaries; decoding restores every type.
const wire = JSON.stringify(toTransport(record));
const decoded = fromTransport(JSON.parse(wire)) as { id: RecordId; score: Float64 };
export const sameKey: boolean = decoded.id.key === 7n && decoded.score.value === 1;

import { createSqlJobStore, jobStateSchema } from '@cossackframework/core/jobs';
import { createFastDB, MemoryPendingWriteStore, sqlDatabase } from '@cossackframework/fastdb';

const db = createFastDB({ url: 'http://127.0.0.1:4321', token: 'local-service-token', pending: new MemoryPendingWriteStore() });

// The same lease and fencing semantics as the D1 ledger, on a FastDB relational table.
export const jobs = createSqlJobStore(sqlDatabase(db, { kind: 'jobs' }));
export const schema: string = jobStateSchema;
